/* Approval is a protected server document, never a local device/admin flag. */
(function(){
 const ACCESS='salons/default/arrivalAccess/counter';
 let auth,db,project,dialog,change=()=>{},stopAuth,stopAccess,key='',generation=0,watchGeneration=0,entry=null,serverFresh=false,busy=false,wasCounter=false,recoveringAnon=null;
 let state={writer:false,reason:'一般裝置：到店狀態唯讀',uid:null};
 function allowed(user,token,access){return !!user&&!user.isAnonymous&&token?.claims?.firebase?.sign_in_provider==='password'&&access?.enabled===true&&access.uid===user.uid&&Number.isSafeInteger(access.minAuthTime)&&access.minAuthTime>=0&&Number.isSafeInteger(token.claims.auth_time)&&token.claims.auth_time>access.minAuthTime}
 const accessRef=()=>db.collection('salons').doc('default').collection('arrivalAccess').doc('counter');
 function publish(writer,reason){if(writer)wasCounter=true;state={writer:!!writer&&navigator.onLine,reason,uid:auth?.currentUser?.uid||null};updateDialog();updateRecovery();change(state)}
 function fail(error){stopAccess?.();stopAccess=null;key='';watchGeneration++;entry=null;serverFresh=false;publish(false,['auth/user-token-expired','auth/id-token-expired','auth/invalid-user-token','auth/user-disabled'].includes(error?.code)?'登入已失效，請重新登入櫃檯帳號':'櫃檯授權未生效或已撤銷，請管理者核對帳號與授權')}
 async function session(){const user=auth?.currentUser;if(!user||user.isAnonymous)throw Error('到店標記僅限核准的櫃檯帳號，其他裝置為唯讀');try{return {user,token:await user.getIdTokenResult()}}catch(error){fail(error);throw Error('櫃檯登入已失效，請至設定重新登入，原預約輸入已保留')}}
 async function authorizeTransaction(tx){const {user,token}=await session();let snapshot;try{snapshot=await tx.get(accessRef())}catch(error){fail(error);throw Error('櫃檯授權無法確認或已撤銷，未儲存標記')};if(!snapshot.exists||!allowed(user,token,snapshot.data())){fail();throw Error('櫃檯授權未生效、已撤銷或登入已過期，未儲存標記')}return true}
 function configure(authentication,database,projectId,onChange){auth=authentication;db=database;project=projectId;change=onChange||(()=>{})}
 async function observe(user,force=false){
  const ticket=++generation;
  if(!user||user.isAnonymous){stopAccess?.();stopAccess=null;key='';entry=null;serverFresh=false;publish(false,wasCounter?'櫃檯登入已退出或失效，到店狀態唯讀；可重新登入':'一般裝置：到店狀態唯讀');return}
  let token;try{token=await user.getIdTokenResult()}catch(error){if(ticket===generation)fail(error);return}
  if(ticket!==generation)return;
  const next=user.uid+':'+token.claims.auth_time;
  if(token.claims.firebase?.sign_in_provider!=='password'){stopAccess?.();stopAccess=null;key='';publish(false,'此帳號不是櫃檯專用密碼帳號，到店狀態唯讀');return}
  if(next===key&&stopAccess&&!force){publish(serverFresh&&allowed(user,token,entry),serverFresh&&allowed(user,token,entry)?'櫃檯已授權':'櫃檯授權未生效或已撤銷');return}
  stopAccess?.();key=next;entry=null;serverFresh=false;publish(false,'正在向伺服器確認櫃檯授權……');
  const watch=++watchGeneration;stopAccess=accessRef().onSnapshot({includeMetadataChanges:true},snapshot=>{
   if(watch!==watchGeneration||key!==next||auth.currentUser?.uid!==user.uid)return;
   entry=snapshot.data();serverFresh=snapshot.metadata?.fromCache!==true&&snapshot.metadata?.hasPendingWrites!==true;
   const ok=serverFresh&&allowed(user,token,entry);publish(ok,ok?'櫃檯已授權':!serverFresh?'尚未取得伺服器授權確認，暫為唯讀':'櫃檯授權未生效、已撤銷或需重新登入');
  },error=>{if(watch===watchGeneration&&key===next)fail(error)});
 }
 async function refresh(){if(!auth)return;if(!auth.currentUser&&window.salonAuthConnection){publish(false,'登入身分已失效，請恢復原帳號；未自動改為匿名登入');return}if(!auth.currentUser&&navigator.onLine&&!busy){const pending=recoveringAnon||(recoveringAnon=auth.signInAnonymously());try{await pending}catch(_){publish(false,'一般登入恢復失敗，請連線後重試');return}finally{if(recoveringAnon===pending)recoveringAnon=null}}await observe(auth.currentUser,true)}
 function guard(){if(window.SALON_ARRIVAL_CONFIG?.phase==='compatibility')throw Error('相容版本尚未開放櫃檯登入，請等候完成安全切換');if(window.SALON_ARRIVAL_CONFIG?.enabled!==true||project!=='demo-salon-counter')throw Error('櫃檯授權目前只供隔離測試，尚未開放正式登入')}
 async function accountSwitchSafe(){const connection=window.salonAuthConnection;if(!connection||!auth.currentUser)return;await connection.verifyPending?.();const s=connection.status();if(s.pendingOperations||s.unresolvedReceipts||s.uncertainWrites||(s.verification&&s.verification!=='clear'))throw Error('仍有待送或待核對操作，請先確認完成，再切換登入身分。')}
 async function login(email,password){guard();if(!navigator.onLine)throw Error('目前離線，請連線後再登入');if(!email.trim()||!password)throw Error('請填寫管理者建立的櫃檯帳號及密碼');await accountSwitchSafe();try{if(recoveringAnon)await recoveringAnon.catch(()=>{});await auth.setPersistence('local');await auth.signInWithEmailAndPassword(email.trim(),password);if(window.salonAuthConnection&&!window.salonAuthConnection.status().ready)await window.salonAuthConnection.recover({acknowledgePending:true});await refresh()}catch(error){if(error?.message?.includes('請填寫'))throw error;throw Error(error?.code==='auth/operation-not-allowed'?'尚未啟用 Email／密碼登入，請管理者設定':error?.code==='auth/web-storage-unsupported'?'瀏覽器無法保留登入，請使用一般 Safari 視窗並檢查網站資料設定':error?.code==='auth/network-request-failed'?'無法連線登入，請稍後重試':'登入未成功，請核對櫃檯帳號及密碼；預約輸入已保留')}}
 async function logout(){guard();await accountSwitchSafe();wasCounter=false;stopAccess?.();stopAccess=null;key='';entry=null;serverFresh=false;publish(false,'正在登出櫃檯帳號……');try{await auth.signOut();await auth.signInAnonymously();if(window.salonAuthConnection)await window.salonAuthConnection.recover({acknowledgePending:true});await refresh()}catch(error){publish(false,'櫃檯已退出或連線失敗，請連線後重新確認登入');throw Error('登入狀態切換未完成，請連線後重試')}}
 function updateRecovery(){const actions=document.querySelector('#modal .actions');if(!actions)return;let button=document.getElementById('counterAuthInEditor');if(!button){button=document.createElement('button');button.id='counterAuthInEditor';button.className='counterRecovery';button.type='button';button.textContent='重新確認櫃檯登入';button.onclick=open;actions.append(button)}button.hidden=state.writer||!(wasCounter||(auth?.currentUser&&!auth.currentUser.isAnonymous))}
 function updateDialog(){if(!dialog)return;dialog.querySelector('.counterStatus').textContent=state.reason;dialog.querySelector('.counterUID').textContent=auth?.currentUser&&!auth.currentUser.isAnonymous?'帳號 UID：'+auth.currentUser.uid:'目前為一般匿名裝置';dialog.querySelector('.counterAccount').textContent=auth?.currentUser&&!auth.currentUser.isAnonymous?'櫃檯帳號：'+(auth.currentUser.email||'未提供 Email'):'';dialog.querySelector('.counterEpoch').textContent='目前授權起算秒數參考：'+Math.floor(Date.now()/1000);dialog.querySelector('.counterSignout').hidden=!auth?.currentUser||auth.currentUser.isAnonymous;dialog.querySelectorAll('button,input').forEach(el=>el.disabled=busy)}
 function createDialog(){if(dialog)return;dialog=document.createElement('dialog');dialog.className='counterDialog';dialog.setAttribute('aria-labelledby','counterHeading');dialog.innerHTML='<h2 id="counterHeading">櫃檯專用授權</h2><p class="counterStatus" role="status"></p><small>隔離候選版：請勿輸入正式帳號密碼。</small><p class="counterAccount"></p><p class="counterUID"></p><p>僅在櫃檯公用裝置登入。帳號不是實體裝置綁定，請勿在私人手機使用。</p><form class="counterLogin"><label>櫃檯帳號 Email<input type="email" name="email" autocomplete="username" required></label><label>密碼<input type="password" name="password" autocomplete="current-password" required></label><button type="submit">登入／重新登入</button></form><p class="counterResult" role="status"></p><button type="button" class="counterRefresh">重新確認授權</button><button type="button" class="counterSignout">登出這台裝置的櫃檯帳號</button><small class="counterEpoch"></small><button type="button" class="counterClose">關閉</button>';
  const run=async action=>{if(busy)return;busy=true;updateDialog();dialog.querySelector('.counterResult').textContent='處理中……';try{await action();dialog.querySelector('.counterResult').textContent='已完成，授權結果以上方狀態為準'}catch(error){dialog.querySelector('.counterResult').textContent=error.message}finally{dialog.querySelector('[name=password]').value='';busy=false;updateDialog()}};
  dialog.querySelector('form').onsubmit=event=>{event.preventDefault();run(()=>login(dialog.querySelector('[name=email]').value,dialog.querySelector('[name=password]').value))};dialog.querySelector('.counterRefresh').onclick=()=>run(refresh);dialog.querySelector('.counterSignout').onclick=()=>run(logout);dialog.querySelector('.counterClose').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{dialog.querySelector('[name=password]').value=''});dialog.addEventListener('cancel',event=>{if(busy)event.preventDefault()});document.body.append(dialog);
 }
 function open(){if(window.SALON_ARRIVAL_CONFIG?.phase==='compatibility'){window.salonNotify?.('相容版本尚未開放櫃檯登入');return}createDialog();dialog.querySelector('[name=email]').value=auth?.currentUser?.email||'';dialog.querySelector('.counterResult').textContent='';updateDialog();dialog.showModal();refresh()}
 function start(){if(window.SALON_ARRIVAL_CONFIG?.phase==='compatibility'||stopAuth)return;const menu=document.querySelector('#settingsHomeModal .settingsMenu');if(menu&&!document.getElementById('counterAuthOpen')){const button=document.createElement('button');button.type='button';button.id='counterAuthOpen';button.innerHTML='<strong>櫃檯授權</strong><small>專用帳號登入、權限狀態與登出</small>';button.onclick=()=>{document.getElementById('settingsHomeModal').classList.remove('open');open()};menu.append(button)}stopAuth=auth.onIdTokenChanged(user=>observe(user),fail);window.addEventListener('offline',()=>publish(false,'目前離線，到店標記暫為唯讀'));window.addEventListener('online',refresh);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()})}
 window.SalonCounterAuth={ACCESS,allowed,configure,start,open,login,logout,refresh,authorizeTransaction,canWrite:()=>window.SALON_ARRIVAL_CONFIG?.phase!=='compatibility'&&state.writer&&navigator.onLine&&(!window.salonAuthConnection||window.salonAuthConnection.status().ready),getState:()=>({...state})};
})();
